public MutationResponse configureMinima(WeatherMinimaConfigRequest request) {
    // 规范化：窗口按 (startUtc, endUtc) 排序，使集合顺序不影响幂等指纹
    List<WeatherWindowDto> sorted = new ArrayList<>(request.windows());
    sorted.sort(Comparator.comparing(WeatherWindowDto::startUtc).thenComparing(WeatherWindowDto::endUtc));
    WeatherMinimaConfigRequest normalized = new WeatherMinimaConfigRequest(request.requestId(), request.operator(), request.zoneId(), sorted);
    return idempotency.execute(request.requestId(), KIND_WEATHER_MINIMA_CONFIG, normalized, () -> {
        if (airspaceRepo.findZone(request.zoneId()) == null) → 404 ZONE_NOT_FOUND
