        for (WeatherMinimaPo m : weatherRepo.findMinima(zoneId)) {
            windows.add(new WeatherWindowDto(m.windowStartUtc(), m.windowEndUtc(),
                    m.minVisibilityM(), m.minCloudBaseM()));
        }
        return new WeatherMinimaDetailDto(zoneId, windows);
    }

